package com.aicommerce.platform.delivery.application.port;
import java.util.UUID; import com.aicommerce.platform.delivery.domain.PlatformDesiredState;
public record PlatformAdCommand(PlatformCommandIdentity identity,UUID platformAdUuid,UUID platformAdSetUuid,UUID productUuid,UUID assetUuid,UUID generationOutputUuid,UUID reviewDecisionUuid,String approvedChecksumSha256,String creativeMappingKey,PlatformDesiredState desiredState){public PlatformAdCommand{PlatformContractSupport.req(identity);PlatformContractSupport.req(platformAdUuid);PlatformContractSupport.req(platformAdSetUuid);PlatformContractSupport.req(productUuid);PlatformContractSupport.req(assetUuid);PlatformContractSupport.req(generationOutputUuid);PlatformContractSupport.req(reviewDecisionUuid);approvedChecksumSha256=PlatformContractSupport.hash(approvedChecksumSha256);if(creativeMappingKey==null||creativeMappingKey.isBlank()||desiredState!=PlatformDesiredState.PAUSED)throw PlatformContractSupport.invalid();}}
